\label{thm:main}
For every \(\varepsilon\in(0,1)\), there exist constants
\(c_{\varepsilon}>0\) and \(d_0=d_0(\varepsilon)\in\mathbb{N}\) such that
\begin{equation}\label{eq:main-finite}
 N_{\Phi,\mathrm{qmc}}(\varepsilon,d)
 \geq N_{\Phi,+}(\varepsilon,d)
 \geq \frac{c_{\varepsilon}}{d}
 \left(\frac{3+2 \sqrt{3}}{6}\right)^d
\end{equation}
for every \(d\geq d_0\).  In particular,
\begin{equation*}
 \liminf_{d\to\infty}
 N_{\Phi,+}(\varepsilon,d)^{1/d}
 \geq \frac{3+2 \sqrt{3}}{6}=1.07735\ldots.
\end{equation*}
Consequently (note that the factor $1/d$ in \eqref{eq:main-finite} is absorbed), the \(L\log L\)-Luxemburg discrepancy with nonnegative weights, and hence also the classical QMC weight discrepancy, suffers from the curse of dimensionality.

\label{lem:modular}
Let \(f\) be a bounded measurable function not a.e. zero.  Then the function
\[
 K \mapsto \rho_\Phi(f/K)\qquad \mbox{for } K>0,
\]
is continuous and strictly decreasing, tends to \(+\infty\) as \(K \downarrow0\), and tends to \(0\) as \(K\to\infty\).  Consequently,
\begin{equation*}
 \rho_\Phi\!\left(\frac{f}{\left\lVert f\right\rVert_{\Phi}}\right)=1.
\end{equation*}
Moreover, if \(K \geq\left\lVert f\right\rVert_{\Phi}\), then $\rho_\Phi(f/K)\leq 1$.

\label{prop:initial}
The initial $L \log L$-Luxemburg discrepancy is
\begin{equation*}
\operatorname{disc}_{\Phi}(0,d)= \left\lVert v_d\right\rVert_{\Phi} =\left(c_0+o(1)\right) \frac{d}{2^d},\qquad \mbox{where } c_0:=\log2-\frac12.
\end{equation*}

We prove the equivalent assertion 
\begin{equation}\label{eq:ad-asymptotic}
 \lim_{d\to\infty}\frac{\alpha_d}{d}=c_0.
\end{equation}

By Lemma~\ref{lem:modular} with $f(\boldsymbol{t})=v_d(\boldsymbol{t})$, the defining modular equals one at \(K =\left\lVert v_d\right\rVert_{\Phi}\), i.e., 
\[
 1=\int_{[0,1]^d}
 \frac{v_d(\boldsymbol t)}{\left\lVert v_d\right\rVert_{\Phi}}
 \log\!\left(1+\frac{v_d(\boldsymbol t)}{\left\lVert v_d\right\rVert_{\Phi}}\right)
 \,\mathrm{d}\boldsymbol t.
\]
Using \eqref{eq:nud} and \(\left\lVert v_d\right\rVert_{\Phi}=\alpha_d 2^{-d}\), we obtain
\begin{equation}\label{eq:ad-equation}
 \alpha_d
 =\mathbb{E}_{\nu_d}\left[
 \log\!\left(1+\frac{2^d \, v_d(\boldsymbol T)}{\alpha_d}\right)\right],
\end{equation}
where \(\boldsymbol T=(T_1,\ldots,T_d)\) has distribution \(\nu_d\).

We first establish crude bounds on \(\alpha_d\).  By Lemma~\ref{lem:L1-embedding}, $2^{-d}=\left\lVert v_d\right\rVert_{L_1}\leq\kappa \, \left\lVert v_d\right\rVert_{\Phi}$, and hence
\begin{equation}\label{eq:ad-lower}
 \alpha_d\geq\kappa^{-1}.
\end{equation}
On the other hand, the concavity of \(x\mapsto\log(1+x)\), followed by Jensen's inequality in \eqref{eq:ad-equation}, gives
\begin{align*}
 \alpha_d
 &\leq\log\!\left(1+
 \frac{2^d \, \mathbb{E}_{\nu_d}[v_d(\boldsymbol T)]}{\alpha_d}\right).
\end{align*}
A direct product calculation yields
\[
 \mathbb{E}_{\nu_d}[v_d(\boldsymbol T)]
 =2^d\int_{[0,1]^d}v_d(\boldsymbol t)^2\,\mathrm{d}\boldsymbol t
 =\left(\frac23\right)^d.
\]
Therefore,
\begin{equation}\label{eq:ad-upper}
 \alpha_d
 \leq\log\!\left(1+\frac{(4/3)^d}{\alpha_d}\right)
 \leq\log\!\left(1+\kappa \left(\tfrac43\right)^d\right)
 \leq d\log\tfrac43+\log(1+\kappa).
\end{equation}
It follows from \eqref{eq:ad-lower} and \eqref{eq:ad-upper} that
\begin{equation}\label{eq:logad}
\lim_{d \rightarrow \infty} \frac{\log \alpha_d}{d} = 0.
\end{equation}

Under \(\mu\) from \eqref{eq:productmeasure}, the random variable \(Y:=-\log T\) is exponentially distributed with rate two.  Indeed, for \(y\geq0\),
\[
 \mu(Y>y)=\mu(T< {\rm e}^{-y})=\int_0^{{\rm e}^{-y}}2t\,\mathrm{d} t={\rm e}^{-2y}.
\]
Consequently, if
\begin{equation}\label{eq:Sd}
 S_d:=-\log v_d(\boldsymbol T)=\sum_{j=1}^d(-\log T_j),
\end{equation}
then
\begin{equation}\label{eq:Sd-moments}
 \mathbb{E}_{\nu_d}[S_d]=\frac d2,
 \qquad
 \operatorname{Var}_{\nu_d}[S_d]=\frac d4.
\end{equation}
We rewrite Eq.~\eqref{eq:ad-equation} as
\begin{equation*}                       
 \alpha_d  =\mathbb{E}_{\nu_d}\left[\ell\!\left(d\log2-S_d-\log \alpha_d\right)\right]
 \qquad \mbox{where }  \ell(x):=\log(1+{\rm e}^x).
\end{equation*}
Dividing by \(d\) and using the elementary estimate $x_+\leq\ell(x)\leq x_+ +\log2$ for every \(x\in\mathbb{R}\), where $x_+:=\max\{x,0\}$, we obtain
\begin{equation}\label{eq:ad-positive-part}
 \left|
 \frac{\alpha_d}{d}
 -\mathbb{E}_{\nu_d}\left[\left(
 \log2-\frac{S_d}{d}-\frac{\log \alpha_d}{d}
 \right)_+\right]
 \right|
 \leq\frac{\log2}{d}.
\end{equation}
The map \(x\mapsto x_+\) is 1-Lipschitz.  Hence, by \eqref{eq:Sd-moments} and Cauchy-Schwarz,
\begin{align*}
 \left|
 \mathbb{E}_{\nu_d}\left[\left(
 \log2-\frac{S_d}{d}-\frac{\log \alpha_d}{d}
 \right)_+\right]-c_0
 \right|
 &\leq
 \mathbb{E}_{\nu_d}\left[\left|\frac{S_d}{d}-\frac12\right|\right]
 +\frac{|\log \alpha_d|}{d}\\
 &\leq
 \sqrt{\operatorname{Var}_{\nu_d}\left[\frac{S_d}{d}\right]}
 +\frac{|\log \alpha_d|}{d}
 =\frac{1}{2\sqrt d}+\frac{|\log \alpha_d|}{d}.
\end{align*}
The right-hand side tends to zero by \eqref{eq:logad}.  Combining this with \eqref{eq:ad-positive-part} proves \eqref{eq:ad-asymptotic}, and the final result follows from \(\left\lVert v_d\right\rVert_{\Phi}=\alpha_d2^{-d}\).

\label{lem:modular-estimate}
Suppose that
\begin{equation}\label{eq:small-norm}
 \left\lVert \Delta_{\mathcal{P},\mathcal{A}}\right\rVert_{\Phi}\leq\varepsilon \left\lVert v_d\right\rVert_{\Phi} \qquad \mbox{for some } \varepsilon \in (0,1).
\end{equation}
Then
\begin{equation}\label{eq:modular-X}
 \mathbb{E}_{\nu_d}\left[
 X\log\!\left(1+\frac{v_d}{\varepsilon \, \left\lVert v_d\right\rVert_{\Phi}}X\right)
 \right]
 \leq\varepsilon \alpha_d \qquad \mbox{and} \qquad \mathbb{E}_{\nu_d}[X]\leq\kappa\varepsilon \alpha_d.
\end{equation}
Consequently,
\begin{equation}\label{eq:EZ-upper}
 \mathbb{E}_{\nu_d}[Z]\leq1+\kappa\varepsilon \alpha_d.
\end{equation}

The case $\Delta_{\mathcal{P},\mathcal{A}}=0$ a.e. is trivial. If $\Delta_{\mathcal{P},\mathcal{A}}$ is not a.e. zero, then Lemma~\ref{lem:modular} and \eqref{eq:small-norm} give
\[
 \int_{[0,1]^d}
 \Phi\!\left(\frac{|\Delta_{\mathcal{P},\mathcal{A}}(\boldsymbol{t})|}{\varepsilon \left\lVert v_d\right\rVert_{\Phi}}\right)
 \,\mathrm{d}\boldsymbol t\leq1.
\]
Since \(|\Delta_{\mathcal{P},\mathcal{A}}|=v_dX\), the definition of \(\Phi\), the identity
\(\left\lVert v_d\right\rVert_{\Phi}=\alpha_d2^{-d}\), and the change of measure \eqref{eq:nud} give
\begin{align*}
 1
 &\geq\int_{[0,1]^d}
 \frac{v_d(\boldsymbol{t})X(\boldsymbol{t})}{\varepsilon \left\lVert v_d\right\rVert_{\Phi}}
 \log\!\left(1+\frac{v_d(\boldsymbol{t})X(\boldsymbol{t})}{\varepsilon \left\lVert v_d\right\rVert_{\Phi}}\right)
 \,\mathrm{d}\boldsymbol t=\frac{1}{\varepsilon \alpha_d}
 \mathbb{E}_{\nu_d}\left[
 X\log\!\left(1+\frac{v_d}{\varepsilon \left\lVert v_d\right\rVert_{\Phi}}X\right)
 \right].
\end{align*}
This implies the first estimate in \eqref{eq:modular-X}. Furthermore, Lemma~\ref{lem:L1-embedding} and \eqref{eq:small-norm} imply $\left\lVert \Delta_{\mathcal{P},\mathcal{A}}\right\rVert_{L_1}
 \leq\kappa\varepsilon \left\lVert v_d\right\rVert_{\Phi}$. Using \(\,\mathrm{d}\nu_d=(v_d/2^{-d})\,\mathrm{d}\boldsymbol t\), we obtain
\[
 \mathbb{E}_{\nu_d}[X]
 =\frac{1}{2^{-d}}\int_{[0,1]^d}v_d(\boldsymbol{t})X(\boldsymbol{t})\,\mathrm{d}\boldsymbol t
 =\frac{\left\lVert \Delta_{\mathcal{P},\mathcal{A}}\right\rVert_{L_1}}{2^{-d}}
 \leq\kappa\varepsilon\frac{\left\lVert v_d\right\rVert_{\Phi}}{2^{-d}}
 =\kappa\varepsilon \alpha_d,
\]
which is the second estimate in \eqref{eq:modular-X}. Finally, \(Z\leq1+|Z-1|=1+X\), which proves~\eqref{eq:EZ-upper}.

\label{lem:localization}
Fix \(\varepsilon\in(0,1)\).  Choose numbers \(\delta\) and \(\tau\) satisfying
\begin{equation}\label{eq:delta-tau}
 0<\delta<c_0(1-\varepsilon) \qquad \mbox{ and } \qquad 
 0<\tau<1-\frac{\varepsilon c_0}{c_0-\delta}.
\end{equation}
Define
\begin{equation*}                  
 I_\delta:=2\delta-\log(1+2\delta)>0
\qquad \mbox{ and } \qquad 
 L_d:=\log\!\left(
 1+\frac{\tau {\rm e}^{(c_0-\delta)d}}{\varepsilon \alpha_d}
 \right).
\end{equation*}
If \eqref{eq:small-norm} holds, then
\begin{equation}\label{eq:moment-lower-explicit}
 \mathbb{E}_{\nu_d}[Z^{1/2}]
 \geq
 1-{\rm e}^{-I_\delta d}-\tau-\frac{\varepsilon \alpha_d}{L_d}.
\end{equation}
In particular, there exist \(b=b(\varepsilon,\delta,\tau)>0\) and
\(d_1=d_1(\varepsilon,\delta,\tau)\) such that
\begin{equation}\label{eq:moment-lower}
 \mathbb{E}_{\nu_d}[Z^{1/2}]\geq b \qquad \mbox{for all } d\geq d_1.
\end{equation}
The constants \(b\) and \(d_1\) are independent of the particular nodes and weights.

\label{lem:one-dimensional}
Let \(\boldsymbol x\in[0,1]^d\) and define
\begin{equation}\label{eq:Yx}
 Y_{\boldsymbol x}(\boldsymbol t)
 :=\frac{\mathbf{1}_{\{\boldsymbol x<\boldsymbol t\}}}{v_d(\boldsymbol t)}
\end{equation}
when \(v_d(\boldsymbol t)>0\), and set it equal to zero otherwise. Set $R:=\sqrt{4 \sqrt{3}-6}$. Then
\begin{equation}\label{eq:tensor-contraction}
\mathbb{E}_{\nu_d}[Y_{\boldsymbol x}^{1/2}] \leq R^d \left(\mathbb{E}_{\nu_d}[Y_{\boldsymbol x}]\right)^{1/2}.
\end{equation}

Because of the product structure it suffices to prove the result in the one-dimensional case for $x \in [0,1)$. (Note that if some $x_j=1$, both sides of \eqref{eq:tensor-contraction} vanish.) With respect to \(\mu\) from \eqref{eq:productmeasure}, direct integration gives
\begin{align*}
 \mathbb{E}_\mu[Y_x]
 &=\int_x^1\frac1t\,2t\,\mathrm{d} t=2(1-x),\ \mbox{and}
 \\
 \mathbb{E}_\mu [Y_x^{1/2}]
 &=\int_x^1\frac1{t^{1/2}}\,2t\,\mathrm{d} t
 =\frac{4}{3}\left(1-x^{3/2}\right).
\end{align*}
Thus for $x \in [0,1)$, $$\frac{\mathbb{E}_\mu [Y_x^{1/2}]}{(\mathbb{E}_\mu[Y_x])^{1/2}}=\frac{2 \sqrt{2}}{3} \frac{1-x^{3/2}}{(1-x)^{1/2}} \le R,$$ where the last inequality follows from a one-variable maximization (equality holds for $x=\tfrac12(2-\sqrt{3})$).

\label{lem:mixture}
Let \(G_{\mathcal{P},\mathcal{A}}\) be given by \eqref{eq:Gintro}, with weights \(a_k\geq0\), and let \(Z=G_{\mathcal{P},\mathcal{A}}/v_d\) be as in \eqref{eq:Z}. Then
\begin{equation*}
\mathbb{E}_{\nu_d}[Z^{1/2}] \leq R^d N^{1/2} \left(\mathbb{E}_{\nu_d}[Z]\right)^{1/2}.
\end{equation*}

For \(\theta \in (0,1)\) and \(z_1,\ldots,z_N\geq0\) we will use the estimates
\begin{equation}\label{eq:subadditivity}
 \left(\sum_{k=1}^N z_k\right)^\theta
 \leq\sum_{k=1}^N z_k^\theta \le N^{1-\theta} \left(\sum_{k=1}^N z_k\right)^\theta.
\end{equation}
Here the left inequality is well known (see, e.g., \cite[Eq.~(4.26)]{LP26} for a proof) and the right inequality follows from Jensen's inequality for the concave function \(x\mapsto x^\theta\), applied to the uniform probability measure on \(\{1,\ldots,N\}\).

By \eqref{eq:Yx}, $Z=\sum_{k=1}^Na_kY_{\boldsymbol x_k}$ $\nu_d$-almost surely and all summands are nonnegative. Using \eqref{eq:subadditivity} with $\theta=1/2$ and \eqref{eq:tensor-contraction}, we get
\begin{align*}
 \mathbb{E}_{\nu_d}[Z^{1/2}] \leq\sum_{k=1}^N a_k^{1/2}
 \mathbb{E}_{\nu_d}[Y_{\boldsymbol x_k}^{1/2}]\leq R^d  \sum_{k=1}^N \left(a_k\mathbb{E}_{\nu_d}[Y_{\boldsymbol x_k}]\right)^{1/2} \le R^d N^{1/2}
 \left(\mathbb{E}_{\nu_d}[Z]\right)^{1/2},
\end{align*}
as claimed.

Fix \(\varepsilon\in(0,1)\) and choose
\(\delta\) and \(\tau\) satisfying \eqref{eq:delta-tau}.  Let an $N$-point set $\mathcal{P}$ and corresponding nonnegative weights $\mathcal{A}$ satisfy $\left\lVert \Delta_{\mathcal{P},\mathcal{A}}\right\rVert_{\Phi}\leq\varepsilon \left\lVert v_d\right\rVert_{\Phi}$.

By Lemma~\ref{lem:localization}, there are constants \(b>0\) and \(d_1\) such that
\begin{equation*}
\mathbb{E}_{\nu_d}[Z^{1/2}]\geq b \qquad \mbox{for every } d\geq d_1,
\end{equation*}
and by Lemma~\ref{lem:mixture} and \eqref{eq:EZ-upper},
\begin{equation*}
 \mathbb{E}_{\nu_d}[Z^{1/2}] \leq R^d N^{1/2}
 \left(1+\kappa\varepsilon \alpha_d\right)^{1/2}.
\end{equation*}
Combining these two estimates, we obtain the explicit bound
\begin{equation}\label{eq:explicit-rule-bound}
 N
 \geq b^2
 \left(1+\kappa\varepsilon \alpha_d\right)^{-1}
 R^{-2d}.
\end{equation}

By \eqref{eq:ad-asymptotic}, \(\alpha_d/d\to c_0\).  Therefore, after increasing \(d_1\) if necessary, we may assume that \(\alpha_d\leq2c_0d\).  Since
\(d\geq1\), we have $1+\kappa\varepsilon \alpha_d
 \leq (1+2\kappa\varepsilon c_0)d$.
Thus \eqref{eq:explicit-rule-bound} implies
\[
 N
 \geq \frac{c_{\varepsilon}}{d}
 R^{-2d},
\]
where one may take $c_{\varepsilon} :=b^2 (1+2\kappa\varepsilon c_0)^{-1}>0$. This lower bound holds for every $N$-point set $\mathcal{P}$ with corresponding nonnegative weights $\mathcal{A}$ whose normalized $L\log L$-Luxemburg discrepancy is at most \(\varepsilon\). 

If the infimum defining \(\operatorname{disc}_{\Phi,+}(N,d)\) is not attained we proceed as follows. Fix $\varepsilon\in(0,1)$, put $\varepsilon':=(1+\varepsilon)/2\in(\varepsilon,1)$, and choose $\delta$ and $\tau$ satisfying \eqref{eq:delta-tau} with $\varepsilon'$ in place of $\varepsilon$. Let $N:=N_{\Phi,+}(\varepsilon,d)$. Since $\operatorname{disc}_{\Phi,+}(N,d)\le\varepsilon\,\operatorname{disc}_{\Phi}(0,d)<\varepsilon'\operatorname{disc}_{\Phi}(0,d)$, there exist an $N$-point set $\mathcal{P}$ and nonnegative weights $\mathcal{A}$ with $\left\lVert \Delta_{\mathcal{P},\mathcal{A}}\right\rVert_{\Phi}\le\varepsilon'\left\lVert v_d\right\rVert_{\Phi}$. The theorem follows.

\label{le:OrHo}
Let $f$ be bounded and measurable and $g$ measurable. We have
\begin{equation}\label{eq:orlicz-holder-associate}
        \int_{[0,1]^d} |f(\boldsymbol{t})g(\boldsymbol{t})|\,\mathrm{d}\boldsymbol{t}
        \le
        \left\lVert f\right\rVert_{\Phi}\left\lVert g\right\rVert_{\Phi,*}.
\end{equation}
The inequality is sharp. For bounded, measurable and not a.e.~zero  functions define the so-called norming function
\[
        g_f(\boldsymbol{t})
        :=
        \frac{
        \Phi'\left(\frac{|f(\boldsymbol{t})|}{\left\lVert f\right\rVert_{\Phi}}\right)
        }{\int_{[0,1]^d}
        \frac{|f(\boldsymbol{s})|}{\left\lVert f\right\rVert_{\Phi}}
        \Phi'\left(\frac{|f(\boldsymbol{s})|}{\left\lVert f\right\rVert_{\Phi}}\right)
        \,\mathrm{d}\boldsymbol{s}
        } .
\]
Then
\[
        \left\lVert g_f\right\rVert_{\Phi,*}=1
        \qquad \mbox{ and } \qquad
        \int_{[0,1]^d}|f(\boldsymbol{t})|g_f(\boldsymbol{t})\,\mathrm{d}\boldsymbol{t}
        =\left\lVert f\right\rVert_{\Phi} ,
\]
i.e., for $f$ and $g_f$ we have equality in \eqref{eq:orlicz-holder-associate}.

For $f \not=0$ we have 
\begin{align*}
\int_{[0,1]^d}|f(\boldsymbol{t})g(\boldsymbol{t})|\,\mathrm{d}\boldsymbol{t} = & \|f\|_{\Phi} \int_{[0,1]^d} \frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}} |g(\boldsymbol{t})| \,\mathrm{d} \boldsymbol{t} \\ \le &  \|f\|_{\Phi} \sup_{\|h\|_{\Phi}\le 1} \int_{[0,1]^d} |h(\boldsymbol{t}) g(\boldsymbol{t})| \,\mathrm{d} \boldsymbol{t} = \|f\|_{\Phi}  \left\lVert g\right\rVert_{\Phi,*}.  
\end{align*}
This proves \eqref{eq:orlicz-holder-associate}. It remains to prove the sharpness of the bound.

On the one hand we have
\begin{align*}
\|g_f\|_{\Phi,\ast} = & \sup_{\|h\|_{\Phi} \le 1} \frac{\int_{[0,1]^d}|h(\boldsymbol{t})| \Phi'\left(\frac{|f(\boldsymbol{t})|}{\left\lVert f\right\rVert_{\Phi}}\right) \,\mathrm{d} \boldsymbol{t}}{
\int_{[0,1]^d} \frac{|f(\boldsymbol{s})|}{\left\lVert f\right\rVert_{\Phi}} \Phi'\left(\frac{|f(\boldsymbol{s})|}{\left\lVert f\right\rVert_{\Phi}}\right) \,\mathrm{d}\boldsymbol{s}}\ge  \frac{\int_{[0,1]^d} \frac{|f(\boldsymbol{t})|}{\left\lVert f\right\rVert_{\Phi}} \Phi'\left(\frac{|f(\boldsymbol{t})|}{\left\lVert f\right\rVert_{\Phi}}\right)\,\mathrm{d} \boldsymbol{t}}{
\int_{[0,1]^d} \frac{|f(\boldsymbol{s})|}{\left\lVert f\right\rVert_{\Phi}} \Phi'\left(\frac{|f(\boldsymbol{s})|}{\left\lVert f\right\rVert_{\Phi}}\right)\,\mathrm{d}\boldsymbol{s}}=1.
\end{align*}
On the other hand, choose any function $h$ with $\|h\|_{\Phi}\le 1$. Then for any $K>1\ge \|h\|_{\Phi}$ we have $\rho_{\Phi}(h/K) \le 1$, and monotone convergence for $K \downarrow 1$ gives $\int_{[0,1]^d}\Phi(|h(\boldsymbol{t})|) \,\mathrm{d} \boldsymbol{t} \le 1$. Using Young's inequality $v w \le \Phi(v)+\Phi^{\ast}(w)$ with $v=|h(\boldsymbol{t})|$ and $w=\Phi'(|f(\boldsymbol{t})|/\|f\|_{\Phi})$ pointwise and integration over $[0,1]^d$ yields 
\begin{align*}
\lefteqn{\int_{[0,1]^d} |h(\boldsymbol{t})| \Phi'\left(\frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}}\right) \,\mathrm{d} \boldsymbol{t}}\\
& \le \int_{[0,1]^d} \Phi(|h(\boldsymbol{t})|) \,\mathrm{d} \boldsymbol{t}   +  \int_{[0,1]^d} \Phi^{\ast}\left(\Phi'\left(\frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}}\right)\right) \,\mathrm{d} \boldsymbol{t}  \\
& =  \int_{[0,1]^d} \Phi(|h(\boldsymbol{t})|) \,\mathrm{d} \boldsymbol{t}   +  \int_{[0,1]^d} \frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}} \Phi'\left(\frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}}\right) \,\mathrm{d} \boldsymbol{t} -  \int_{[0,1]^d} \Phi\left(\frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}}\right) \,\mathrm{d} \boldsymbol{t},
\end{align*}
where we used \eqref{eq:compAalpha}. Since $\int_{[0,1]^d} \Phi(|h(\boldsymbol{t})|) \,\mathrm{d} \boldsymbol{t} \le 1$ and $\int_{[0,1]^d} \Phi\left(\frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}}\right) \,\mathrm{d} \boldsymbol{t}=1$ it follows that 
$$\int_{[0,1]^d} |h(\boldsymbol{t})| \Phi'\left(\frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}}\right) \,\mathrm{d} \boldsymbol{t} \le \int_{[0,1]^d} \frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}} \Phi'\left(\frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}}\right) \,\mathrm{d} \boldsymbol{t}.$$ Thus, for every function $h$ with $\|h\|_{\Phi}\le 1$ we have $$\int_{[0,1]^d} |h(\boldsymbol{t}) g_f(\boldsymbol{t})| \,\mathrm{d} \boldsymbol{t}=\frac{\int_{[0,1]^d}|h(\boldsymbol{t})| \Phi'\left(\frac{|f(\boldsymbol{t})|}{\left\lVert f\right\rVert_{\Phi}}\right)\,\mathrm{d} \boldsymbol{t}}{
\int_{[0,1]^d} \frac{|f(\boldsymbol{t})|}{\left\lVert f\right\rVert_{\Phi}} \Phi'\left(\frac{|f(\boldsymbol{t})|}{\left\lVert f\right\rVert_{\Phi}}\right) \,\mathrm{d}\boldsymbol{t}}\le 1$$ and this implies that $\|g_f\|_{\Phi,\ast} \le 1$. Together with the lower bound we deduce $\|g_f\|_{\Phi,\ast}=1$.


Finally, it is obvious that 
$$\int_{[0,1]^d}|f(\boldsymbol{t}) g_f(\boldsymbol{t})|\,\mathrm{d}\boldsymbol{t} =  \frac{\int_{[0,1]^d}|f(\boldsymbol{t})| 
        \Phi'\left(\frac{|f(\boldsymbol{t})|}{\|f\|_{\Phi}}\right) \,\mathrm{d} \boldsymbol{t}
        }{\int_{[0,1]^d}
        \frac{|f(\boldsymbol{s})|}{\|f\|_{\Phi}}
        \Phi'\left(\frac{|f(\boldsymbol{s})|}{\|f\|_{\Phi}}\right)
        \,\mathrm{d}\boldsymbol{s}} = \|f\|_{\Phi}.$$
This finishes the proof.

Let $r:=\min(p,2) \in (1,2]$. We show the existence of a number $c_r>0$ such that $\Phi(t) \le c_r t^r$ for all $t \ge 0$. For \(r=2\), the claim follows from \(\log(1+t)\le t\). For $r \in (1,2)$ we have $t^{1-r} \log(1+t) \le t^{2-r} \rightarrow 0$ as $t \to 0$, since $r<2$. Thus $\lim_{t \to 0} \Phi(t)/t^r=0$. On the other hand, $$\lim_{t \to \infty} \frac{\Phi(t)}{t^r}= \lim_{t \to \infty} t^{1-r} \log(1+t)=0,$$ since $r>1$. Since $t \mapsto \Phi(t)/t^r$ is continuous on $(0,\infty)$, this proves the claim. 

The assertion is trivial if $f=0$. Now let $0\ne f \in L_r$. Set $K=c_r^{1/r} \|f\|_{L_r}$. Then we have 
\begin{align*}
\int_{[0,1]^d} \Phi\left(\frac{|f(\boldsymbol{t})|}{K}\right) \,\mathrm{d} \boldsymbol{t}
&\le c_r \int_{[0,1]^d} \left(\frac{|f(\boldsymbol{t})|}{K}\right)^r \,\mathrm{d} \boldsymbol{t}\\
&=\frac{c_r}{K^r} \int_{[0,1]^d} |f(\boldsymbol{t})|^r \,\mathrm{d} \boldsymbol{t}
=\frac{c_r}{c_r \|f\|_{L_r}^r} \|f\|_{L_r}^r=1.
\end{align*}
Hence, $\|f\|_{\Phi} \le c_r^{1/r} \|f\|_{L_r}$.

Now, for $p \in (1,2]$ we have $r=p$ and hence $\|f\|_{\Phi}\le c_p^{1/p} \|f\|_{L_p}$. For $p >2$ we have $r=2$ and hence $\|f\|_{\Phi}\le c_2^{1/2} \|f\|_{L_2} \le c_2^{1/2} \|f\|_{L_p}$, due to the monotonicity of the $L_p$-norm. This finishes the proof. \hfill $\qed
